        y: Math.cos(att.pitch) * Math.cos(att.roll),
        z: -sy * bodyX + cy * bodyZ,
      };

      if (prevObs) {
        const pAtt = prevObs.att, pRates = prevObs.rates, pVel = prevObs.vel;
