          target = { x: prevGate.x + 0.32, y: prevGate.y, z: prevGate.z };
          vxFf = 0.8;
          kpZ = 8.5; kdZ = 5.0; kpY = 7.5; kdY = 4.5;
        } else {
          const dz = p.z - gate.z;
          const dy = p.y - gate.y;
          const dx = gate.x - p.x;

