            const alignX = gate.x - 0.30;
            target = { x: alignX, y: gate.y, z: gate.z };
            if (Math.abs(dz) > 0.028 || Math.abs(dy) > 0.10) {
              target.x = Math.min(alignX, gate.x - 0.36);
            }
            kpX = 5.5; kdX = 4.2;
            kpZ = 7.8; kdZ = 4.8;
            kpY = 7.2; kdY = 4.5;

