              p.x > gate.x - 0.45 &&
              p.x < gate.x - 0.08 &&
              v.x < 0.45 &&
              Math.abs(dz) < 0.017 &&
              Math.abs(zPred) < 0.020 &&
              Math.abs(v.z) < 0.08 &&
              Math.abs(dy) < 0.065 &&
              Math.abs(yPred) < 0.08 &&
              Math.abs(v.y) < 0.18 &&
